class RiverChannelObstructionTest{static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]a){int n=128;var e=new EnvironmentMap(new float[n*n]);e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*n+x,level=90+z/8;e.height[i]=level+2;if(x>=56&&x<=72){e.height[i]=level-4;e.water[i]=level;e.river[i]=.8f;}}int spike=64*n+64;e.height[spike]=120;e.water[65*n+64]+=9;var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);var r=RiverBanks.apply(node,e,n,n,62,2024,0,0,()->false);for(int z=0;z<n;z++)for(int x=56;x<=72;x++){int i=z*n+x,water=r.waterY(i,62);check(Math.round(r.height[i])<water,"channel obstruction at "+x+","+z);check(water-r.height[i]<=5.01,"bounded channel depth");if(x<72)check(Math.abs(water-r.waterY(i+1,62))<=1,"cross-channel water spike");if(z+1<n)check(Math.abs(water-r.waterY(i+n,62))<=1,"downstream water jump");}check(r.height[spike]<r.waterY(spike,62),"dry rock pillar cut out");check(e.height[spike]==120,"source unchanged");var join=new EnvironmentMap(EnvironmentMap.filled(32*32,105));join.water=EnvironmentMap.filled(1024,62);join.river=new float[1024];for(int z=0;z<32;z++)for(int x=12;x<=20;x++){int k=z*32+x;join.river[k]=1;join.water[k]=z<8?100:90;join.height[k]=z<8?80:86;}RiverBanks.finishChannels(join,32,62,5);check(join.water[4*32+16]==100,"lake surface preserved");check(join.height[4*32+16]==80,"lake depth preserved");for(int z=7;z<31;z++){int k=z*32+16;check(Math.abs(join.waterY(k,62)-join.waterY(k+32,62))<=1,"lake outlet has no abrupt water wall");check(join.waterY(k,62)>Math.round(join.height[k]),"outlet stays wet");}
var lakeSteps=new EnvironmentMap(EnvironmentMap.filled(16*16,70));lakeSteps.water=EnvironmentMap.filled(256,100);lakeSteps.river=EnvironmentMap.filled(256,1);lakeSteps.water[8*16+8]=104;RiverBanks.finishChannels(lakeSteps,16,62,5);check(lakeSteps.water[8*16+8]<=101,"deep-water surface tower removed");check(lakeSteps.water[4*16+4]==100,"interior lake level unchanged");
var tilted=new EnvironmentMap(EnvironmentMap.filled(64*64,120));tilted.water=EnvironmentMap.filled(4096,62);tilted.river=new float[4096];for(int z=0;z<64;z++)for(int x=24;x<=40;x++){int k=z*64+x;tilted.river[k]=1-Math.abs(x-32)/20f;tilted.water[k]=90+(x-24)/2;tilted.height[k]=tilted.water[k]-4;}RiverBanks.crossSections(tilted,64,64,62,5,()->false);for(int x=24;x<=40;x++)check(tilted.water[32*64+x]==tilted.water[32*64+32],"river width stays level");
System.out.println("PASS: dry rock obstruction removed, isolated water tower removed, continuous wet channel, bounded depth and adjacent water steps");}}
